 JSONObject metadata(int index){JSONObject m=a.heroes.optJSONObject(index);if(m==null)m=new JSONObject();JSONObject cached=CacheFiles.parsed("cinema.meta."+m.optString("type",a.heroType)+"."+m.optString("id"));if(DetailMetadata.useful(cached))try{m=DetailMetadata.merge(m,cached);}catch(Exception ignored){}return m;}
 FrameLayout picture(JSONObject m){FrameLayout slide=new FadeFrame(a);ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);slide.addView(image,new FrameLayout.LayoutParams(-1,-1));if(a.homeChrome==null)a.homeChrome=new HomeChrome(a);a.homeChrome.dressHero(slide,image,m);return slide;}
